#!/bin/bash
# bootstrap.sh — build a native Crystal compiler from the *patched* source.
#
# The exception landing pads are generated by whichever compiler compiles the
# code, so patching the source we hand to the distribution's compiler is not
# enough: the distribution's compiler emits its own landing-pad shape. To change
# codegen, the compiler itself has to be rebuilt with the patch, and then used to
# cross-compile the wasm compiler.
#
#   bash bootstrap.sh        # → $OUT/bin/crystal-native
set -uo pipefail

HERE="$(cd "$(dirname "$0")" && pwd)"
OUT="${OUT:-/root/bc-crystal}"
SRC="$OUT/src"
DIST_CRYSTAL="${DIST_CRYSTAL:-/opt/crystal-1.17.0/bin/crystal}"

if [ ! -d "$SRC" ]; then
	echo "no patched source at $SRC — create it (copy the distribution's src and" >&2
	echo "run apply-patches.py) before bootstrapping" >&2
	exit 1
fi

python3 "$HERE/apply-patches.py" "$SRC" || exit 1

mkdir -p "$OUT/bin"
cd "$SRC" || exit 1

# Build natively: the wasm LLVM pinning must not apply here, so the distribution
# compiler uses a native llvm-config -- and it must be one Crystal 1.17 supports
# (LLVM 8-20). `find-llvm-config.sh` takes the first on PATH, which on this
# machine was llvm-config-21, so a supported one is chosen explicitly.
#
# Needs the native development libraries too: libpcre3-dev (for -lpcre) and
# libgc-dev, which the distribution's own build requires.
BOOTSTRAP_LLVM_CONFIG="${BOOTSTRAP_LLVM_CONFIG:-}"
if [ -z "$BOOTSTRAP_LLVM_CONFIG" ]; then
	for v in 20 19 18 17 16; do
		if [ -x "/usr/lib/llvm-$v/bin/llvm-config" ]; then
			BOOTSTRAP_LLVM_CONFIG="/usr/lib/llvm-$v/bin/llvm-config"
			break
		fi
	done
fi
echo "bootstrap llvm-config: ${BOOTSTRAP_LLVM_CONFIG:-<distribution default>}"

env -u LLVM_VERSION -u LLVM_TARGETS -u LLVM_LDFLAGS \
	${BOOTSTRAP_LLVM_CONFIG:+LLVM_CONFIG="$BOOTSTRAP_LLVM_CONFIG"} \
	"$DIST_CRYSTAL" build compiler/crystal.cr \
	-Di_know_what_im_doing \
	-Dwithout_playground \
	-Dwithout_docs \
	-Dwithout_interpreter \
	-o "$OUT/bin/crystal-native"
rc=$?
echo "bootstrap rc=$rc"
ls -l "$OUT/bin/crystal-native" 2>/dev/null
exit $rc
